strategy_source:
function (ctx, params) 
{
    if (isTRUE(params$interrupt) && identical(ctx$ts_utc, "2020-01-03T16:00:00Z")) {
        options(ledgr.interrupt = TRUE)
    }
    target <- ctx$hold()
    if (ctx$ts_utc >= "2020-01-03T16:00:00Z" && "AAA" %in% names(target)) 
        target[["AAA"]] <- 0
    target
}
